import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:tugas7/cart_model.dart';
import 'package:tugas7/cart_page.dart';

class ProductPage extends StatelessWidget {
  ProductPage({super.key});

  final products = [
    Product(
      'Beras',
      'Beras pandanwangi enak dan harum',
      'data:image/webp;base64,',
    ),

    Product(
      'Indomie',
      'Indomie goreng enak',
      'https://th.bing.com/th/id/OIP.ehLguY4erSbyX4jegb3_AQHaFO?w=278&h=197&c=7&r=0&o=7&dpr=1.5&pid=1.7&rm=3',
    ),

    Product(
      'Pocari Sweet',
      'Minuman isotonik cocok untuk olahraga',
      'https://th.bing.com/th/id/OIP.09KNg_4NQUGGTxVkEX75CgHaHa?w=164&h=180&c=7&r=0&o=7&dpr=1.5&pid=1.7&rm=3',
    ),
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("WARUNG MADURA 24JAM"),
        centerTitle: true,
        backgroundColor: Colors.blue,
        foregroundColor: Colors.white,
        actions: [
          Padding(
            padding: EdgeInsets.only(right: 15),
            child: Consumer<KeranjangModel>(
              builder: (context, cart, child) {
                return Badge(
                  label: Text('${cart.totalItems}'),
                  isLabelVisible: cart.totalItems > 0,

                  child: IconButton(
                    onPressed: () {
                      Navigator.push(
                        context,
                        MaterialPageRoute(builder: (context) => CartPage()),
                      );
                    },
                    icon: Icon(Icons.shopping_cart_checkout),
                  ),
                );
              },
            ),
          ),
        ],
      ),

      body: ListView.builder(
        itemCount: products.length,
        itemBuilder: (context, index) {
          final item = products[index];
          return Card(
            margin: EdgeInsets.all(5),
            child: ListTile(
              leading: CircleAvatar(
                backgroundImage: NetworkImage(item.gambar)
                ),
              title: Text(item.nama),
              subtitle: Text(item.deskripsi),
              trailing: IconButton(
                onPressed: () {
                  Provider.of<KeranjangModel>(context, listen: false).add(item);
                },
                icon: Icon(Icons.add_shopping_cart),
              ),
            ),
          );
        },
      ),
    );
  }
}
